final double min = 0;
final double max = 10;
String selectedValue = '';
@override
void initState() {
  selectedValue = min.toString();
  super.initState();
}
@override
Widget build(BuildContext context) {
  return Scaffold(
    appBar: AppBar(title: const Text('Animated Weight Picker')),
    body: Center(
      child: AnimatedWeightPicker(
        min: min,
        max: max,
        onChange: (newValue) {
          setState(() {
            selectedValue = newValue;
          });
        },
      ),
    ),
  );
}
